insert into public.board_exam_questions
select * from jsonb_populate_recordset(null::public.board_exam_questions, '[{"id":"17468bc6-a867-0f7d-0a60-e094135c0816","stem":"Em março de 2024, Juliana praticou crime cuja pena era de reclusão de 1 a 3 anos. Em julho de 2025, durante a ação penal e antes da sentença, entrou em vigor lei que elevou a pena para 2 a 5 anos. Ao sentenciar em 2026, o magistrado deverá:","board":"UFAC","state":"AC","options":{"A":"Aplicar a lei nova mais severa, pelo tempus regit actum.","B":"Aplicar a lei antiga mais branda, que terá ultratividade benéfica, sem retroação da lei mais gravosa.","C":"Combinar a pena mínima antiga com a máxima nova.","D":"Suspender o processo até manifestação do STF."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"Aplica-se a lei vigente ao tempo do fato (tempus regit actum). A lei posterior mais gravosa não retroage; a lei anterior mais benéfica conserva ultratividade. Fundamento: CF, art. 5º, XL, e CP, art. 2º.","figure_urls":[],"item_number":1,"legal_basis":[{"lei":"Constituição Federal","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal","artigo":"art. 5º, XL"},{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 1º e 2º"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Aplicação da lei penal no tempo","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"B","import_unique_key":"0e093717eaa39feeb18e55cc28e5bb7613c291dca10ada22dd6986dfe88f4013","syllabus_topic_id":null,"import_content_key":"0e093717eaa39feeb18e55cc28e5bb7613c291dca10ada22dd6986dfe88f4013","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"23ef985e-841b-47e3-b836-e087eb55f002","stem":"Diante de fraude financeira com ativos digitais, suponha que, no caso concreto, a conduta não se enquadre nos elementos do art. 171 nem em outro tipo penal específico. O magistrado aplica por analogia o estelionato para condenar o réu, invocando a função social do Judiciário. Considerando a legalidade estrita, a decisão:","board":"UFAC","state":"AC","options":{"A":"É ilegítima, pois a analogia in malam partem é vedada no Direito Penal incriminador.","B":"É legítima diante de clamor público e omissão legislativa.","C":"É válida porque o juiz pode criar tipos penais temporários.","D":"É interpretação analógica expressamente permitida pelo encerramento do art. 171."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"A analogia não pode criar crime ou ampliar incriminação em prejuízo do réu. A cláusula “qualquer outro meio fraudulento” do art. 171 só permite interpretação dentro dos elementos do tipo; se os fatos não se enquadram neles nem em outro tipo, não se pode condenar por analogia in malam partem. Fundamento: CF, art. 5º, XXXIX, e CP, art. 1º.","figure_urls":[],"item_number":2,"legal_basis":[{"lei":"Constituição Federal","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal","artigo":"art. 5º, XXXIX"},{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 1º e 171"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Princípio da legalidade e analogia in malam partem","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"A","import_unique_key":"455d975c5e1ad92d06da5cf47cfd2a4e13586936ba888f084614127dbdf93d30","syllabus_topic_id":null,"import_content_key":"455d975c5e1ad92d06da5cf47cfd2a4e13586936ba888f084614127dbdf93d30","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"6294d84b-43ec-82d2-992f-2ffd2051b87a","stem":"Henrique praticou delito em 2024, quando a lei previa reclusão de 2 a 6 anos e multa de 50 a 100 dias-multa. Lei de 2025 reduziu a reclusão para 1 a 4 anos, mas elevou a multa para 200 a 400 dias-multa. O juiz combina a reclusão da lei nova e a multa da lei antiga. À luz da vedação à lex tertia reconhecida pelo STF no Tema 169 (no caso da Lei de Drogas) e refletida na Súmula 501/STJ, a atuação:","board":"UFAC","state":"AC","options":{"A":"É válida, pois a retroatividade benéfica permite conjugar preceitos.","B":"É inconstitucional, por criar terceira norma (lex tertia) não emanada do legislador.","C":"É admissível para réus primários em crimes sem violência.","D":"É interpretação extensiva favorável irrestritamente admitida."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O juiz não pode selecionar fragmentos mais favoráveis de leis sucessivas para construir uma terceira norma (lex tertia); deve comparar os regimes integrais e aplicar o mais favorável. O Tema 169/STF e a Súmula 501/STJ tratam especificamente do conflito entre as leis de drogas, como precedente para a vedação à conjugação.","figure_urls":[],"item_number":3,"legal_basis":[{"lei":"STF — Tema 169","url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=2684368&numeroProcesso=600817&numeroTema=169","title":"STF — Tema 169","artigo":"RE 600.817"},{"lei":"STJ — Súmula 501","url":"https://scon.stj.jus.br/SCON/sumstj/doc.jsp?b=SUMU&h=true&i=1&l=10&livre=%40NUM%3D%22501%22&ordenacao=-%40NUM&p=true","title":"STJ — Súmula 501","artigo":"Lei 11.343/2006 e Lei 6.368/1976"}],"review_note":"Revisão concluída em 13/11/2026. Corrigida a referência original a Tema 418/STF: o precedente pertinente é o Tema 169/STF, específico ao conflito entre as leis de drogas; a Súmula 501/STJ também trata dessa hipótese. Gabarito B confirmado. A marcação manuscrita no PDF não é gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Combinação de leis penais e lex tertia","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"B","import_unique_key":"325808842d63db76dd2a56cb9b05b19e0ef3ff4a801bd3a559c6c046385dfc95","syllabus_topic_id":null,"import_content_key":"325808842d63db76dd2a56cb9b05b19e0ef3ff4a801bd3a559c6c046385dfc95","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"2abc3261-9241-8485-c77a-867d427bd38b","stem":"Rodrigo iniciou extorsão mediante sequestro em maio de 2025 e manteve a vítima em cativeiro até novembro. Lei penal mais severa entrou em vigor em setembro, enquanto a vítima ainda estava privada da liberdade. Conforme a Súmula 711 do STF, o juiz deve aplicar:","board":"UFAC","state":"AC","options":{"A":"A lei antiga mais benéfica.","B":"A lei nova mais grave, vigente antes de cessada a permanência.","C":"Uma média proporcional entre as penas.","D":"A lei antiga para a prisão e a nova para o regime."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"A extorsão mediante sequestro é crime permanente. Pela Súmula 711/STF, aplica-se a lei mais grave que entra em vigor antes de cessar a permanência, pois a consumação ainda se prolonga durante a vigência da lei nova.","figure_urls":[],"item_number":4,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 4º e 159"},{"lei":"STF — Súmula 711","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=30&sumula=711","title":"STF — Súmula 711","artigo":"Súmula 711"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Lei penal no tempo — crime permanente","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"B","import_unique_key":"fb49e5ac5997d18363cac7b2930dd9f76b65fce7faaa2db7b2c2ecd6b40bb2b4","syllabus_topic_id":null,"import_content_key":"fb49e5ac5997d18363cac7b2930dd9f76b65fce7faaa2db7b2c2ecd6b40bb2b4","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"06ee4eb3-1c1b-6db5-71f2-5de800c93c05","stem":"Gustavo envia do Brasil um dispositivo explosivo artesanal destinado a matar seu desafeto. O pacote é detonado na residência da vítima, em país vizinho, causando ferimentos gravíssimos. Nos termos do art. 6º do CP, o crime considera-se praticado:","board":"UFAC","state":"AC","options":{"A":"Somente no país vizinho, local do resultado.","B":"Somente no Brasil, local da conduta.","C":"No Brasil e no país estrangeiro, considerando-se o lugar da conduta e o do resultado.","D":"Em nenhum dos dois países sem tratado bilateral."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O art. 6º do CP adota a teoria da ubiquidade: considera-se lugar do crime tanto onde ocorreu a ação ou omissão, no todo ou em parte, quanto onde se produziu ou deveria produzir-se o resultado.","figure_urls":[],"item_number":5,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 6º"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Lugar do crime — teoria da ubiquidade","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"C","import_unique_key":"7903d87e649d4936972c4b4e16c7a583bf9392d1834f4dc0cd9a7ac57f60e994","syllabus_topic_id":null,"import_content_key":"7903d87e649d4936972c4b4e16c7a583bf9392d1834f4dc0cd9a7ac57f60e994","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"8380edb5-ce20-9b93-3fd8-c6540b388508","stem":"Enquanto passava férias na Europa, um cidadão de nacionalidade francesa cometeu dolosamente o assassinato do Ministro das Relações Exteriores do Brasil e de um Senador brasileiro que participavam de uma conferência oficial no mesmo recinto. Após o fato, o homicida foi julgado, condenado a pena branda e perdoado pela justiça daquele país europeu. De acordo com o art. 7º do Código Penal brasileiro:","board":"UFAC","state":"AC","options":{"A":"O agente responderá pela lei brasileira mediante extraterritorialidade incondicionada em relação a ambas as mortes.","B":"A lei brasileira não poderá ser aplicada a nenhum dos fatos, sob pena de violação frontal ao princípio do non bis in idem internacional.","C":"A lei brasileira não incide pela extraterritorialidade incondicionada, pois as vítimas não são o Presidente da República; a hipótese do §3º é condicionada a requisitos cumulativos, inclusive ingresso no Brasil e ausência de perdão no exterior, requisito que não se verifica no caso.","D":"A lei brasileira aplica-se automaticamente caso a autoridade judiciária local não execute a extradição voluntária no prazo de 90 dias."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:56:15.575797+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O art. 7º, I, a, prevê extraterritorialidade incondicionada para crime contra a vida ou a liberdade do Presidente da República, não para crimes contra Ministro ou Senador apenas por ocuparem esses cargos. O §3º prevê extraterritorialidade condicionada para crime cometido por estrangeiro contra brasileiro no exterior, exigindo cumulativamente os requisitos legais, entre eles entrada do agente no Brasil e ausência de perdão no exterior. Como o enunciado informa perdão estrangeiro, essa condição não se verifica.","figure_urls":[],"item_number":6,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 7º, I, a, §§ 2º e 3º"}],"review_note":"Revisão concluída em 13/11/2026. Gabarito C confirmado com explicitação dos requisitos cumulativos do art. 7º, §3º, do CP; o perdão concedido no exterior impede o preenchimento da condição legal. Marcação manuscrita do PDF é indicação visual, não gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Extraterritorialidade da lei penal brasileira — art. 7º do CP","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"C","import_unique_key":"5ca8d9c15850c580e5e6988605627b9e2a59e3cc2becb994ab76e2dc5faa7788","syllabus_topic_id":null,"import_content_key":"5ca8d9c15850c580e5e6988605627b9e2a59e3cc2becb994ab76e2dc5faa7788","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"3efb78b4-0954-996a-1c74-d27ed68562d0","stem":"A Revolução Finalista de Hans Welzel, incorporada pela reforma da Parte Geral do Código Penal em 1984, alterou a localização dos elementos subjetivos do delito. Sob a ótica do Finalismo:","board":"UFAC","state":"AC","options":{"A":"A conduta é neutra e dolo e culpa permanecem na culpabilidade.","B":"Dolo e culpa foram deslocados da culpabilidade para o fato típico, integrando a conduta humana.","C":"A culpabilidade foi eliminada do conceito de crime.","D":"A conduta é definida exclusivamente pelo resultado físico exterior."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"No finalismo, dolo e culpa integram a conduta e são analisados no fato típico; a culpabilidade fica composta por imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa. Trata-se de construção dogmática consolidada na doutrina, não de frase literal do Código Penal.","figure_urls":[],"item_number":7,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 13 e 18"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Finalismo e localização do dolo e da culpa","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"B","import_unique_key":"841908e1c083fdd5171ec8563ee1cc1aa3f80bcd0fb8214017e4bf4f0b13eb7c","syllabus_topic_id":null,"import_content_key":"841908e1c083fdd5171ec8563ee1cc1aa3f80bcd0fb8214017e4bf4f0b13eb7c","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"7b36ab87-5870-62af-47e2-2356433f32c6","stem":"Samuel atira com intenção de matar Leandro. Após cirurgia bem-sucedida, três semanas depois, uma viga do teto do hospital desaba por infiltrações antigas e mata Leandro. Considerando o art. 13 do CP, Samuel responderá por:","board":"UFAC","state":"AC","options":{"A":"Homicídio doloso consumado, pois a vítima não estaria no hospital sem os tiros.","B":"Absolvição sumária por rompimento de qualquer vínculo naturalístico.","C":"Homicídio culposo, pois a morte decorreu de circunstância imprevisível.","D":"Tentativa de homicídio, pois a concausa superveniente relativamente independente produziu por si só a morte."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O art. 13, §1º, do CP exclui a imputação do resultado quando uma causa superveniente relativamente independente, por si só, produz a morte. Permanecem imputáveis os atos anteriores; diante do dolo de matar e da não produção do resultado imputável ao disparo, a resposta é tentativa de homicídio.","figure_urls":[],"item_number":11,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 13, caput e §1º"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Concausa superveniente relativamente independente","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"D","import_unique_key":"9fa1503a479cc01d19b87a2f4a0efc33b4fc09304d5cac6faf2f2b5a5110cfca","syllabus_topic_id":null,"import_content_key":"9fa1503a479cc01d19b87a2f4a0efc33b4fc09304d5cac6faf2f2b5a5110cfca","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"fad88519-4579-00e6-00dd-2efceeacbf5c","stem":"Roberto empurra uma pessoa para o lado ao perceber que um bloco de concreto cai em direção à cabeça dela. A vítima sofre luxação e fratura no punho, mas evita ser esmagada. Segundo a imputação objetiva de Claus Roxin, a conduta:","board":"UFAC","state":"AC","options":{"A":"É típica e ilícita, mas exclui a pena por inexigibilidade.","B":"É formalmente típica, porém lícita por estado de necessidade.","C":"É atípica no primeiro degrau, pois diminuiu o risco juridicamente proibido.","D":"É lesão corporal culposa, com perdão judicial."},"subject":"Direito Penal","exam_date":null,"exam_type":"N1","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"Na teoria da imputação objetiva de Roxin, a diminuição de um risco juridicamente proibido pode afastar a imputação objetiva do resultado menos grave quando a intervenção evita dano muito maior. É tese doutrinária: a conclusão depende de a conduta efetivamente reduzir o risco e não criar outro risco proibido autônomo.","figure_urls":[],"item_number":12,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 13 e 23"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Imputação objetiva — diminuição do risco","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:1322775167581fee7fc0cb123dc2fbd84bda90a051dde6634b6c862b82cfd453","content_status":"active","career_category":"Acadêmico","official_answer":"C","import_unique_key":"ff29df30cdac5ae4702c0e2f415dc7109d1e656800df07d0d88188ce42893529","syllabus_topic_id":null,"import_content_key":"ff29df30cdac5ae4702c0e2f415dc7109d1e656800df07d0d88188ce42893529","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"8d9d4d97-2ba2-28f4-3bf2-b8fd2d594134","stem":"Em Tarauacá/AC, Valter, primário e sem antecedentes, subtrai duas caixas de fósforo e um pacote de velas avaliados em R$ 8,00, sem violência ou ameaça. Detido a cem metros, a mercadoria é restituída. Não há notícia de habitualidade ou circunstância concreta de maior reprovabilidade. À luz do HC 84.412/SP do STF e da jurisprudência do STJ:","board":"UFAC","state":"AC","options":{"A":"A insignificância afasta a tipicidade material se presentes mínima ofensividade, ausência de periculosidade social, reduzidíssimo grau de reprovabilidade e inexpressividade da lesão.","B":"A restituição antes da denúncia afasta a tipicidade formal por analogia à Súmula 554 do STF.","C":"O fato é típico, cabendo apenas perdão judicial por bagatela imprópria.","D":"A insignificância é vedada em todos os crimes patrimoniais."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O HC 84.412/SP do STF aponta quatro vetores cumulativos: mínima ofensividade, ausência de periculosidade social, reduzidíssimo grau de reprovabilidade e inexpressividade da lesão. O valor reduzido e a restituição são relevantes, mas não geram insignificância automática; a análise é concreta.","figure_urls":[],"item_number":1,"legal_basis":[{"lei":"STF — HC 84.412/SP","url":"https://noticias.stf.jus.br/postsnoticias/supremo-aplica-principio-da-insignificancia-penal-em-liminar-de-hc/","title":"STF — HC 84.412/SP","artigo":"quatro vetores da insignificância"},{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 155"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Tipicidade material — princípio da insignificância","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"A","import_unique_key":"ba9fb151ba85b73f394c31a504eab4f9dc252c0253ac6a6345c753596886da72","syllabus_topic_id":null,"import_content_key":"ba9fb151ba85b73f394c31a504eab4f9dc252c0253ac6a6345c753596886da72","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"1427d7c9-2e8b-8b97-005f-02a9e7c99e5a","stem":"Rodrigo, com dolo de matar, dispara dois tiros contra Otávio e atinge suas pernas. Ainda com dez munições e sem intervenção externa, decide voluntariamente poupar a vida da vítima, guarda a arma e se afasta. Otávio sofre lesões leves. Nos termos do art. 15 do CP, Rodrigo:","board":"UFAC","state":"AC","options":{"A":"Responde por tentativa cruenta de homicídio.","B":"Responde apenas pelos atos já praticados, como a lesão corporal, por desistência voluntária.","C":"Obtém extinção da punibilidade por arrependimento eficaz.","D":"Praticou fato totalmente atípico, inclusive quanto às lesões."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"Na desistência voluntária, o agente ainda podia prosseguir na execução, mas decide parar por vontade própria. Pelo art. 15 do CP, responde apenas pelos atos já praticados que constituam infração penal; não responde pela tentativa de homicídio.","figure_urls":[],"item_number":2,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 15"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Desistência voluntária — art. 15 do CP","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"B","import_unique_key":"3d5f5174643cdedc150bf2df0d06270c9889c4fa4b0c6f52ad9d9c275f7cd2fb","syllabus_topic_id":null,"import_content_key":"3d5f5174643cdedc150bf2df0d06270c9889c4fa4b0c6f52ad9d9c275f7cd2fb","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"0822b1b2-e0ab-bac8-9351-0dc805fa26b5","stem":"Henrique, tesoureiro de banco em Feijó, tem a esposa grávida sequestrada. Os criminosos ameaçam matá-la se ele não retirar R$ 200.000,00 do cofre. Sem outra alternativa para salvá-la, Henrique obedece. À luz da teoria normativa pura e do art. 22 do CP, Henrique:","board":"UFAC","state":"AC","options":{"A":"Responde por furto qualificado, com atenuante de coação resistível.","B":"Pratica fato atípico porque a coação moral elimina a voluntariedade física.","C":"É isento de pena por coação moral irresistível, que exclui a exigibilidade de conduta diversa; o coator responde.","D":"Responde em coautoria com os sequestradores por peculato."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"A coação moral irresistível exclui a culpabilidade por inexigibilidade de conduta diversa (art. 22 do CP). O coator responde pelo fato; a coação física irresistível teria efeito distinto, sobre a própria conduta.","figure_urls":[],"item_number":3,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 22"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Coação moral irresistível — art. 22 do CP","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"C","import_unique_key":"4e7eea44bb3b6caa168fc971ac741ac7ecdce0e08b5d83f48d42dafc03d5747c","syllabus_topic_id":null,"import_content_key":"4e7eea44bb3b6caa168fc971ac741ac7ecdce0e08b5d83f48d42dafc03d5747c","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"1a7b839b-fc21-03e6-b6d5-c519eb982067","stem":"Joaquim, funcionário público estadual responsável por depósito de mercadorias apreendidas, combina com Jonas, particular que conhece sua condição funcional, o desvio de dez aparelhos de ar-condicionado. Jonas fornece o veículo e transporta os bens. Jonas é reincidente; Joaquim é primário. Conforme o art. 30 do CP:","board":"UFAC","state":"AC","options":{"A":"Jonas responde por furto e Joaquim por peculato, pois a condição funcional nunca se comunica.","B":"Ambos respondem por peculato e a reincidência de Jonas comunica-se a Joaquim.","C":"Jonas responde exclusivamente por receptação dolosa.","D":"Ambos respondem por peculato; a condição funcional elementar comunica-se, mas a reincidência pessoal não."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"A qualidade de funcionário público é elementar do peculato e comunica-se ao particular que a conhece, nos termos do art. 30 do CP. A reincidência de Jonas é circunstância pessoal e não se comunica a Joaquim.","figure_urls":[],"item_number":4,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 30 e 312"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Concurso de pessoas — elementar do peculato","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"D","import_unique_key":"4c286a331e10bd6137603b08eb32c30f069df9c41c0b5c48df79b151a1746026","syllabus_topic_id":null,"import_content_key":"4c286a331e10bd6137603b08eb32c30f069df9c41c0b5c48df79b151a1746026","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"58b1a15d-1668-35d5-9b53-faf98a19ec0c","stem":"Murilo, comprovadamente sob influência de álcool após ingerir três doses de destilado, dirige a 110 km/h em via de 50 km/h. Vê um pedestre a cerca de 80 metros e, confiando em sua habilidade e nos freios, acredita que conseguirá desviar. Mantém a velocidade, tenta manobra brusca e atropela fatalmente o pedestre. A prova indica que não consentiu com o resultado, embora o tenha previsto. A conduta:","board":"UFAC","state":"AC","options":{"A":"É homicídio culposo na direção de veículo automotor, a título de culpa consciente; comprovada a influência de álcool, observa-se a forma do art. 302, §3º, do CTB.","B":"É dolo eventual presumido pela embriaguez e excesso de velocidade.","C":"É dolo eventual porque o desrespeito às regras equivale sempre à assunção do risco.","D":"É crime preterdoloso."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"A culpa consciente ocorre quando o agente prevê o resultado, mas confia concretamente que conseguirá evitá-lo; no dolo eventual, assume o risco. Álcool e velocidade são dados probatórios importantes, mas não permitem presumir dolo eventual. Se comprovada a influência de álcool, deve-se observar também a forma específica do art. 302, §3º, do CTB.","figure_urls":[],"item_number":5,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 18"},{"lei":"Código de Trânsito Brasileiro","url":"https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm","title":"Código de Trânsito Brasileiro","artigo":"art. 302, §3º"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Culpa consciente e dolo eventual","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"A","import_unique_key":"1ba7351271a2b6ec1a15ef2a8f4647070a4b0747ee8e80dae4a36cf739c6080a","syllabus_topic_id":null,"import_content_key":"1ba7351271a2b6ec1a15ef2a8f4647070a4b0747ee8e80dae4a36cf739c6080a","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"2270fe29-fa05-2ed6-d2bc-6ed21f2fd10f","stem":"Vinícius, contador primário, sem violência ou ameaça, subtrai R$ 40.000,00 do cofre da empresa. Vinte dias depois, antes do recebimento da denúncia, restitui espontaneamente todo o valor. É denunciado por furto qualificado por abuso de confiança. Conforme o art. 16 do CP:","board":"UFAC","state":"AC","options":{"A":"A reparação extingue a punibilidade por analogia à Súmula 554 do STF.","B":"Configura arrependimento posterior, com redução obrigatória de pena de um a dois terços na terceira fase.","C":"O benefício só se aplica ao furto simples.","D":"A reparação exclui a tipicidade material."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O art. 16 do CP exige crime sem violência ou grave ameaça e reparação do dano ou restituição voluntária até o recebimento da denúncia ou queixa. Presentes os requisitos, há redução de um a dois terços, aplicada na terceira fase. O simples início de negociação não substitui a reparação efetiva.","figure_urls":[],"item_number":6,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 16"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Arrependimento posterior — art. 16 do CP","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"B","import_unique_key":"6366e3f209ee3c6786a457a0fb71abc5655d93233938b145f27087288f00b134","syllabus_topic_id":null,"import_content_key":"6366e3f209ee3c6786a457a0fb71abc5655d93233938b145f27087288f00b134","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"c7883ff8-bda0-e500-b916-ffe821369875","stem":"Durante cheia do Rio Juruá, Paulo, para salvar o filho de sete anos que se afogava, toma o único barco disponível e lança ao rio mercadorias eletrônicas de alto valor do vizinho, que se perdem. Não havia outro meio hábil. À luz da teoria unitária e do art. 24 do CP, Paulo:","board":"UFAC","state":"AC","options":{"A":"Pratica dano doloso com mera redução de pena.","B":"Age em estado de necessidade exculpante, mantendo o injusto penal.","C":"Age em estado de necessidade justificante, excluindo a ilicitude, pois salva bem de valor manifestamente superior.","D":"Responde por furto de uso e dano culposo."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O art. 24 do CP exclui a ilicitude quando há perigo atual (a doutrina também discute perigo iminente), inevitável por outro meio, não provocado voluntariamente pelo agente, e não era razoável exigir o sacrifício do direito ameaçado. Salvar a vida da criança sacrificando bens patrimoniais de valor inferior caracteriza estado de necessidade justificante, conforme os fatos descritos.","figure_urls":[],"item_number":7,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 24"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Estado de necessidade justificante — art. 24 do CP","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"C","import_unique_key":"e261cc7e8585065deef627694c866c6458734b19a3213e9476dffedb8f3d4fb6","syllabus_topic_id":null,"import_content_key":"e261cc7e8585065deef627694c866c6458734b19a3213e9476dffedb8f3d4fb6","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"4b39f2b7-ed5a-328e-c855-e265dee60f98","stem":"Mateus responde por tentativa de homicídio. Laudo oficial conclui que, ao tempo da ação, por perturbação da saúde mental, não possuía plena capacidade de entender o caráter ilícito do fato e de determinar-se conforme esse entendimento, embora não estivesse inteiramente privado dessa capacidade. O juiz:","board":"UFAC","state":"AC","options":{"A":"Deve absolver impropriamente e internar por prazo indeterminado, como inimputável absoluto.","B":"Pode aplicar pena e medida de segurança cumulativamente pelo sistema do duplo binário.","C":"Deve reconhecer ausência de tipicidade formal por falta de dolo.","D":"Deve condenar com redução de um a dois terços ou, se necessária medida curativa, substituir a pena por medida de segurança."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O art. 26, parágrafo único, prevê semi-imputabilidade quando a capacidade de entendimento ou autodeterminação estava reduzida, sem supressão total. A pena pode ser reduzida de um a dois terços; se presentes os requisitos do art. 98, pode haver substituição por medida de segurança.","figure_urls":[],"item_number":8,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 26, parágrafo único, e 98"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Semi-imputabilidade — art. 26, parágrafo único, do CP","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"D","import_unique_key":"9a5fe52494d0354274cd59cdd830e85538b1a433fa61eac939301340ca198ffe","syllabus_topic_id":null,"import_content_key":"9a5fe52494d0354274cd59cdd830e85538b1a433fa61eac939301340ca198ffe","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"d3f4a88d-7283-d059-8e53-f4d94bd22abb","stem":"Lucas, policial militar em serviço, presencia indivíduo desferindo golpes de facão contra transeuntes. Diante do dever do art. 301 do CPP, imobiliza o agressor com uso moderado da força e o conduz à delegacia. Sob a ótica da tipicidade conglobante de Zaffaroni:","board":"UFAC","state":"AC","options":{"A":"A conduta é atípica na origem por falta de antinormatividade, pois o ordenamento não pode considerar típico comportamento imposto pelo Direito Processual Penal.","B":"A conduta é formal e conglobantemente típica, excluindo-se a ilicitude no segundo degrau.","C":"A teoria conglobante desloca o estrito cumprimento do dever legal para a culpabilidade.","D":"A conduta é típica e ilícita, mas sem culpabilidade por ausência de potencial consciência da ilicitude."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"O art. 301 do CPP autoriza qualquer pessoa a prender quem esteja em flagrante e impõe esse dever às autoridades policiais e seus agentes. Na teoria conglobante de Zaffaroni, a conduta juridicamente ordenada carece de antinormatividade e é considerada atípica; essa é uma leitura doutrinária, não redação expressa do CPP.","figure_urls":[],"item_number":9,"legal_basis":[{"lei":"Código de Processo Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm","title":"Código de Processo Penal","artigo":"art. 301"},{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"art. 23"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Tipicidade conglobante — estrito cumprimento do dever legal","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"A","import_unique_key":"627735216aa3143ae5e1b6489e46fdbe641ede08707023e51d4dc1fbc9448d22","syllabus_topic_id":null,"import_content_key":"627735216aa3143ae5e1b6489e46fdbe641ede08707023e51d4dc1fbc9448d22","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"5d9e698c-74a6-0128-f581-52f15abd16e7","stem":"Leandro entra em loja de conveniência para subtrair mercadorias, esconde três garrafas sob o casaco e passa pelos caixas sem pagar. Desde o início era monitorado por câmeras e seguido por seguranças, que o detêm na calçada. A defesa invoca crime impossível por ineficácia absoluta do meio. Considerando o art. 17 do CP e a Súmula 567 do STJ:","board":"UFAC","state":"AC","options":{"A":"A vigilância contínua torna impossível a consumação, incidindo a Súmula 145 do STF.","B":"A vigilância eletrônica torna o meio absolutamente ineficaz e exclui a tipicidade, ainda que o agente tenha passado pelos caixas.","C":"A ausência de posse mansa e pacífica impede a consumação, pois o furto exige que o agente mantenha a coisa sem perseguição.","D":"O furto está consumado pela teoria da apprehensio/amotio, pois houve inversão da posse, ainda que por breve tempo e com perseguição imediata."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"A vigilância eletrônica ou a presença de seguranças, isoladamente, não torna o furto impossível (Súmula 567/STJ). No caso descrito, Leandro passou pelos caixas, saiu do estabelecimento e foi detido já na calçada: isso indica inversão da posse e consumação pela teoria da apprehensio/amotio e pelo Tema 934/STJ, ainda que a posse seja breve e haja perseguição imediata. O Informativo 886/2026 distingue a hipótese em que o agente é preso ainda dentro da loja, sem inversão efetiva da posse, situação de tentativa. A teoria da illatio não é a adotada.","figure_urls":[],"item_number":10,"legal_basis":[{"lei":"STJ — Súmula 567","url":"https://scon.stj.jus.br/SCON/sumstj/toc.jsp?livre=%27567%27.num.","title":"STJ — Súmula 567","artigo":"vigilância e crime impossível"},{"lei":"STJ — Tema 934","url":"https://processo.stj.jus.br/SCON/GetPDFINFJ?edicao=0572","title":"STJ — Tema 934","artigo":"consumação do furto"},{"lei":"Jurisprudência STJ","url":"https://scon.stj.jus.br/jurisprudencia/externo/informativo/?acao=pesquisarumaedicao&livre=%270886%27.cod.","title":"STJ — Informativo 886/2026","artigo":"distinção tentativa/consumação em furto dentro de loja"},{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 14, 17 e 155"}],"review_note":"Revisão concluída em 13/11/2026. A marcação manuscrita original indicava B; o gabarito técnico foi corrigido para D porque, nos fatos descritos (passagem pelos caixas e detenção na calçada), houve inversão da posse. Fundamento: Tema 934 e Súmula 567 do STJ. Não havia gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Crime impossível e vigilância — Súmula 567 do STJ","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"D","import_unique_key":"7aff50e86d399d33c9ea3f2c1121f34bb05e20f5883638a251b4171b679e34e8","syllabus_topic_id":null,"import_content_key":"7aff50e86d399d33c9ea3f2c1121f34bb05e20f5883638a251b4171b679e34e8","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"21452789-6063-4faa-6029-cbcaf5af0c39","stem":"Caso 1: Gustavo, à noite, vê vulto com facão correndo em sua direção, supõe agressão letal iminente e atira, matando o vizinho que corria para alertar sobre incêndio; o erro era evitável. Caso 2: Renato, credor, aponta arma ao devedor e subtrai seus bens acreditando que a lei autoriza desforço armado privado. À luz da teoria limitada da culpabilidade:","board":"UFAC","state":"AC","options":{"A":"Ambos incorrem em erro de tipo permissivo inevitável e ficam isentos de pena.","B":"Gustavo responde por homicídio doloso com atenuante; Renato é absolvido por exercício regular de direito.","C":"Gustavo incorre em descriminante putativa por erro de fato evitável, podendo responder por culpa imprópria se houver modalidade culposa; Renato incorre em erro de proibição indireto, cuja evitabilidade pode permitir redução de um sexto a um terço.","D":"Ambos incorrem em erro de proibição direto inevitável."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"Gustavo erra sobre pressuposto fático de uma justificante (descriminante putativa); sendo evitável, aplica-se o art. 20, §1º, com possível responsabilização por culpa imprópria se houver modalidade culposa. Renato sabe o que faz, mas erra sobre os limites jurídicos da justificante: erro de proibição indireto (art. 21), que, se evitável, pode reduzir a pena de um sexto a um terço.","figure_urls":[],"item_number":11,"legal_basis":[{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 20, §1º, e 21"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Erro de tipo permissivo e erro de proibição indireto","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"C","import_unique_key":"1f1e8cdc46c20328e088633d04d20653edaf9e0315d87cb6d3b875502db1045d","syllabus_topic_id":null,"import_content_key":"1f1e8cdc46c20328e088633d04d20653edaf9e0315d87cb6d3b875502db1045d","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"},{"id":"bca906c0-de95-5cb2-dc6e-d9ec0afcbd37","stem":"Felipe, Caio e Danilo planejam assaltar joalheria. Felipe e Caio entram armados; Danilo aguarda em carro ligado, encarregado da vigilância externa e fuga. Durante a subtração, Caio dispara contra o vigia, que morre. Os comparsas fogem sem conseguir levar joias. A defesa de Danilo pede participação de menor importância e Felipe invoca cooperação dolosamente distinta. À luz da teoria do domínio do fato e da Súmula 610 do STF:","board":"UFAC","state":"AC","options":{"A":"Danilo deve receber redução por participação de menor importância, pois dirigir a fuga é auxílio periférico.","B":"Felipe responde apenas por roubo tentado, pois não desejava a morte.","C":"Há autoria colateral sucessiva, respondendo apenas Caio por homicídio e os demais por furto tentado.","D":"Pode haver latrocínio consumado em coautoria funcional: a morte consuma o latrocínio mesmo sem subtração, conforme Súmula 610 do STF, sem prejuízo da análise individual do art. 29."},"subject":"Direito Penal","exam_date":null,"exam_type":"N2","exam_year":2026,"created_at":"2026-11-13T22:32:11.055548+00:00","difficulty":"média","source_url":"urn:norteconcursos:uploaded-document:sha256:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","career_name":"Bacharelado em Direito (Modular) — Campus Floresta / Núcleo de Feijó","explanation":"A Súmula 610/STF estabelece que o latrocínio se consuma com a morte, ainda que a subtração não se efetive. O papel de Danilo, previamente ajustado e integrado à vigilância e fuga, pode configurar coautoria funcional; a responsabilidade de cada concorrente pelo resultado morte deve ser individualizada à luz do art. 29, inclusive quanto à previsibilidade do resultado mais grave.","figure_urls":[],"item_number":12,"legal_basis":[{"lei":"STF — Súmula 610","url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=30&sumula=610","title":"STF — Súmula 610","artigo":"consumação do latrocínio"},{"lei":"Código Penal","url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal","artigo":"arts. 29 e 157, §3º"},{"lei":"STJ — HC 20.819/MS","url":"https://scon.stj.jus.br/SCON/pesquisar.jsp?O=JT&b=ACOR&livre=%28HC.clas.+e+%40num%3D%2220819%22%29+ou+%28HC+adj+%2220819%22%29.suce.","title":"STJ — HC 20.819/MS","artigo":"coautoria funcional em caso concreto"}],"review_note":"Revisão jurídica concluída em 13/11/2026. Gabarito técnico conferido com o texto legal e fontes oficiais indicadas em legal_basis. A marcação manuscrita no PDF foi tratada como indicação visual, não como gabarito oficial independente.\nRevisão final 14/11/2026: gabarito visual do PDF confrontado com a análise jurídica; resposta validada. Não há gabarito oficial independente.","verified_at":"2026-11-14T18:26:22.963258+00:00","contest_name":"UFAC — Direito Penal I (2026.2)","needs_visual":false,"support_text":null,"tested_topic":"Concurso de pessoas e latrocínio — Súmula 610 do STF","answer_key_url":"urn:norteconcursos:answer-key:marked-in-source:cc0b74f7b38774b68d5e5ac6751524784af022e654282266ac73308fc69c69ab","content_status":"active","career_category":"Acadêmico","official_answer":"D","import_unique_key":"8d8f87428a36787d5ad04b1f9cde82b0be5cd304939ca1a88424c76d1b7823c6","syllabus_topic_id":null,"import_content_key":"8d8f87428a36787d5ad04b1f9cde82b0be5cd304939ca1a88424c76d1b7823c6","legal_review_required":false,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"}]'::jsonb)
